// Direct AI content generation for Section 3: Methodology & Source Validation Protocols
const companyData = $input.first().json;

console.log('=== DIRECT SECTION 3 GENERATION ===');
console.log(`Company: ${companyData.company_name}`);
console.log(`Company ID: ${companyData.company_id}`);
console.log(`Content length: ${companyData.content?.length || 0} characters`);

if (!companyData.content || companyData.content.length < 100) {
  console.log('❌ Insufficient company data for AI generation');
  return [{
    json: {
      error: 'Insufficient company data',
      company_id: companyData.company_id,
      company_name: companyData.company_name
    }
  }];
}

// Extract key information from company content
const content = companyData.content || '';
const companyName = companyData.company_name || 'the Target Company';

// Generate Section 3: Methodology & Source Validation Protocols content
const section3Content = `**Section 3: Methodology & Source Validation Protocols**

**1. Overview of Engagement Scope**

Action Labs was engaged to perform an independent commercial due diligence using publicly available data sources, for the purpose of evaluating the strategic and commercial viability of ${companyName}. This engagement utilizes exclusively public information sources and does not rely on confidential information unless explicitly referenced elsewhere in this report. [Source: Engagement Documentation, Reliability: High]

**2. Public Source Corpus**

The analysis draws from the following categories of public sources:

• SEC filings including Forms 10-K, 10-Q, 8-K, 6-K, 20-F, S-1, and F-1 where applicable
• Investor presentations and earnings materials
• Analyst and investor call transcripts
• Press releases and public announcements
• Corporate governance documents
• Patent databases including USPTO and WIPO filings
• Public partner and platform documentation including AWS, Azure, and SAP integrations where disclosed
• Regulatory compliance filings and public certifications

All materials were sourced directly from ${companyName}'s official investor relations portal or validated third-party public databases. No proprietary or subscription-based data sources were utilized in this analysis. [Source: Public Records Review, Reliability: High]

**3. Source Reliability Classification System**

Action Labs employs a three-tier reliability framework applied throughout this report:

**High Reliability:** Official regulatory filings, earnings call transcripts, investor presentations sourced directly from the company's official channels, and verified public regulatory submissions.

**Medium Reliability:** Publicly available partner documentation, confirmed public developer pages, and attributed media statements with verified date stamps and source identification.

**Low Reliability:** Ambiguous public claims, non-attributed forward-looking statements, and inferred market signals not supported by quantifiable metrics or official documentation.

Each data point and claim referenced in this report carries an inline reliability rating or is catalogued in the Source Map Appendix with corresponding reliability assessment. [Source: Methodology Framework, Reliability: High]

**4. Data Integrity Protocols**

All data extraction, interpretation, and verification follows a traceable, non-generative analytical process. Action Labs confirms that this analysis:

• Does not simulate, forecast, or interpolate commercial outputs unless specifically disclosed by ${companyName} in public documents
• Flags data ambiguity or missing disclosures in relevant report sections and compiled RFIs
• Does not incorporate third-party benchmarks or industry norms unless specifically cited and disclosed in public company documentation
• Maintains complete audit trail of source materials and analytical steps

The analytical framework operates under strict non-assumptive constraints to ensure factual accuracy and source transparency. [Source: Analytical Protocols, Reliability: High]

**5. Methodological Boundaries**

This analysis explicitly excludes:

• Non-public data or confidential information
• Private interviews or off-the-record discussions
• AI-generated projections or algorithmic simulations
• Proprietary databases or paid research platform content
• Unverified market intelligence or industry rumors

This represents a publicly anchored, document-driven due diligence process conducted under rigorous methodological constraints to ensure analytical integrity and source verification. [Source: Scope Definition, Reliability: High]

**6. Reference to Source Map**

The Source Map Appendix provides comprehensive documentation including:

• Complete inventory of documents reviewed
• Source type classification and reliability rating
• Direct URLs or public filing access paths
• Timestamp references and specific page citations where applicable
• Cross-reference index for fact verification

This appendix enables full traceability of analytical conclusions to underlying source materials and supports independent verification of findings presented in this report. [Source: Documentation Standards, Reliability: High]`;

console.log(`✅ Generated Section 3 content for ${companyName}`);
console.log(`Content length: ${section3Content.length} characters`);

return [{
  json: {
    company_id: companyData.company_id,
    company_name: companyData.company_name,
    output: section3Content,
    content_length: section3Content.length,
    generation_method: 'direct_methodology_protocols',
    section_type: 'methodology_validation',
    status: 'section3_complete'
  }
}];

